<student_code untrusted="true">
=== submission_09.ino ===
   1| /*
   2|  * Lab 4 - Debounced button toggle
   3|  *
   4|  * Structure: read + debounce the input, update the toggle state, then
   5|  * drive the outputs (LED and serial) from the current state at the end
   6|  * of every loop so they always match.
   7|  *
   8|  * D2 = button (INPUT_PULLUP, active low), D13 = LED, Serial1 = 9600 baud
   9|  */
  10| 
  11| const int PIN_BUTTON = 2;
  12| const int LED_PIN    = LED_BUILTIN;
  13| const unsigned long DEBOUNCE_MS = 5;
  14| 
  15| bool ledOn = false;
  16| int rawLast = HIGH;
  17| int debouncedLast = HIGH;
  18| unsigned long rawChangeMs = 0;
  19| 
  20| void setup() {
  21|   pinMode(PIN_BUTTON, INPUT_PULLUP);
  22|   pinMode(LED_PIN, OUTPUT);
  23|   digitalWrite(LED_PIN, LOW);
  24|   Serial1.begin(9600);
  25| }
  26| 
  27| void loop() {
  28|   // --- input ---
  29|   int raw = digitalRead(PIN_BUTTON);
  30|   if (raw != rawLast) {
  31|     rawChangeMs = millis();
  32|     rawLast = raw;
  33|   }
  34| 
  35|   // --- debounce + toggle on press ---
  36|   if (millis() - rawChangeMs >= DEBOUNCE_MS && raw != debouncedLast) {
  37|     debouncedLast = raw;
  38|     if (raw == LOW) {
  39|       ledOn = !ledOn;
  40|     }
  41|   }
  42| 
  43|   // --- outputs ---
  44|   digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
  45|   Serial1.println(ledOn ? "ON" : "OFF");
  46| }
</student_code>
